// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 _value, bytes memory _data) public {
        uint256 initialBal = 10 ether;
        vm.assume(_value <= initialBal);

        Tracker tracker = new Tracker();

        vm.deal(address(c), initialBal);
        address owner = c.owner();
        vm.deal(owner, 1 ether);

        vm.prank(owner);
        c.sendMoney(address(tracker), _value, _data);

        assertTrue(address(tracker).balance == _value);
    }
}

contract Tracker {
    fallback() external payable {}
}
